import { useQuery } from "@tanstack/react-query";
import type { ValidationData } from "@/lib/types";

/**
 * Load public/data/validation.json (generated by the backend
 * pipeline). Resolves to null — rather than erroring — when the file
 * does not exist yet OR carries an older schema (schema_version below
 * 3, e.g. a stale EDAA clone), so consumers can render a graceful
 * pending state.
 */
export function useValidation() {
  return useQuery<ValidationData | null>({
    queryKey: ["validation"],
    queryFn: async () => {
      const basePath =
        process.env.NEXT_PUBLIC_BASE_PATH !== undefined
          ? process.env.NEXT_PUBLIC_BASE_PATH
          : "/us/montana-flat-tax-dashboard";
      const res = await fetch(`${basePath}/data/validation.json`);
      if (!res.ok) return null;
      try {
        const data = (await res.json()) as ValidationData;
        // Stale EDAA files (schema_version 2) carry a different pinned
        // run and anchors — treat them as pending until the Montana
        // pipeline emits schema_version 3.
        if (!data || data.schema_version < 3) return null;
        return data;
      } catch {
        return null;
      }
    },
    staleTime: 5 * 60 * 1000,
    gcTime: 10 * 60 * 1000,
  });
}
